import{_ as t,l as s,o as e,c as n,v as r,p as i,x as l,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"稀疏表","description":"","frontmatter":{"title":"稀疏表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sparse-table.md","filePath":"cs/sparse-table.md","lastUpdated":1789023840000}'),m={name:"cs/sparse-table.md"};function c(_,a,T,u,A,E){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="稀疏表" tabindex="-1">稀疏表 <a class="header-anchor" href="#稀疏表" aria-label="Permalink to &quot;稀疏表&quot;">​</a></h1><div class="epigraph"><p>把每个起点的 $2^k$ 长窗口预先算好，任意区间用两块对齐的 2 的幂盖住；幂等运算下重叠不要紧。</p><footer>—— 据 Bender and Farach-Colton, The LCA Problem Revisited, LATIN 2000；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/prefix-sum-difference">上一课</a>把可逆的区间和收成两次查表。最大值、最小值、最大公因数没有群逆，\\(S[r]-S[l-1]\\) 无意义。本课不重做差分。缺口是静态、<strong>幂等</strong>（或可重叠）的区间查询：稀疏表（sparse table）用 \\(O(n\\log n)\\) 空间换 \\(O(1)\\) 查询。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>区间 \\([l,r]\\) 长度 \\(len=r-l+1\\)，令 \\(k=\\lfloor\\log_2 len\\rfloor\\)。两段 \\([l,l+2^k-1]\\) 与 \\([r-2^k+1,r]\\) 并起来覆盖 \\([l,r]\\)，中间重叠。若运算 \\(\\oplus\\) 满足 \\(x\\oplus x=x\\)（幂等）且结合，则</p> \\[A[l]\\oplus\\cdots\\oplus A[r] = \\mathrm{ST}[k][l]\\oplus \\mathrm{ST}[k][r-2^k+1]. \\]<p>缺口不是新的数组布局，而是<strong>按长度的 2 的幂做倍增预处理</strong>。RMQ（区间最值）是标准实例；LCA 化 RMQ 时同一张表出现，本课只钉序列上的表。</p><p><span class="marginnote">\\(\\mathrm{ST}[k][i]\\) 表示从 \\(i\\) 起长 \\(2^k\\) 的窗口聚合。建表：\\(\\mathrm{ST}[k][i]=\\mathrm{ST}[k-1][i]\\oplus\\mathrm{ST}[k-1][i+2^{k-1}]\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建表 \\(\\Theta(n\\log n)\\)：先 \\(k=0\\) 抄 \\(A\\)，再按 \\(k\\) 升。查询读 \\(\\lfloor\\log_2(r-l+1)\\rfloor\\)，两次表项 \\(\\oplus\\)。\\(\\log\\) 可预处理成每个长度一张表，避免查询时算浮点。数组不可改：改一个点要重建，或退回后课可更新结构。</p>',10)),(e(),i(h,null,{default:l(()=>[d(o,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%9D%99%E6%80%81%E5%BA%8F%E5%88%97%22%5D%20--%3E%20ST%5B%22ST%5Bk%5D%5Bi%5D%20%3D%20%E9%95%BF%202%5Ek%20%E7%AA%97%E5%8F%A3%22%5D%0A%20%20Q%5B%22%E5%8C%BA%E9%97%B4%20%5Bl%2C%20r%5D%22%5D%20--%3E%20TWO%5B%22%E4%B8%A4%E5%9D%97%202%5Ek%20%E8%A6%86%E7%9B%96%22%5D%0A%20%20ST%20--%3E%20TWO%0A%20%20TWO%20--%3E%20IDEM%5B%22%E5%B9%82%E7%AD%89%3A%20%E9%87%8D%E5%8F%A0%E5%8F%AF%E9%87%8D%E5%A4%8D%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与前缀和对照：前缀和靠逆元消去中间，稀疏表靠重叠可重复。两者都静态。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>空间 \\(\\Theta(n\\log n)\\) 个聚合结果，比前缀和厚一截，换来无逆运算。查询两次随机读，常数小于线段树的 \\(O(\\log n)\\) 次访存——静态 RMQ 常因此选稀疏表。不幂等的求和不能用两块覆盖（中间被加两次）；求和请回上一课。</p><p>\\(\\lfloor\\log_2\\rfloor\\) 表本身是 \\(O(n)\\) 预处理。建表顺序必须从小窗口到大窗口，否则引用尚未写出的半段。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Fischer–Heun 的 \\(O(n)\\) 空间 RMQ 写完，也不把树剖成欧拉序。单点修改、区间加都不属于稀疏表合同。需要更新时，下一课树状数组走可加群的另一条路。</p><p>后课默认：静态幂等区间查询可以 \\(O(1)\\)；要改数组，换树状结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稀疏表：\\(O(n\\log n)\\) 建，\\(O(1)\\) 幂等区间查询。</li><li>覆盖用两段等长 2 的幂；求和请用前缀和。</li><li>可更新的加法结构从树状数组开始。</li><li>出处：Bender and Farach-Colton, LATIN 2000；Cormen et al.。</li></ul>',9))])}const S=t(m,[["render",c]]);export{k as __pageData,S as default};
